document.addEventListener('DOMContentLoaded', () => {
    const grid = document.querySelector('.sig-masonry');
    if (!grid) return;

    const resizeAll = () => {
        const rowGap   = parseInt(getComputedStyle(grid).getPropertyValue('grid-row-gap'));
